local Jl=type(P.pasBook)==URe[2359]and type(P.pasBook[Hl])==URe[2359]and P.pasBook[Hl][Il.pid]
if type(Jl)~=URe[2359]then
return Il
end
local Kl={}
for Ll,Ml in pairs(Il)do
Kl[Ll]=Ml
end
Kl.nums={}
for Nl,Ol in pairs(Il.nums or{})do
Kl.nums[Nl]=Ol
end
for Pl,Ql in pairs(Jl.nums or{})do
Kl.nums[Pl]=Ql
end
if Jl.who then
Kl.who=Jl.who
end
return Kl
end
pb.ENEMY_MAX=60
