function pb.plan(Rl)
Rl.planned=true
if not(P.trial and P.trial.study and bb.trialId)then
return
end
local Sl=bb.trialId
local Tl,Ul=pcall(pb.guess,Sl)
local Vl={}
for Wl,Xl in ipairs(Tl and type(Ul)==URe[2359]and Ul or{})do
if Xl.playable and not Xl.hand and pb.sure(Sl,Xl)~=URe[2737]then
if Xl.family==URe[2558]and not(bb.reinc and bb.reinc.id and bb.reinc.id~=Sl)then
bb.reinc={id=Sl,add=tonumber(Xl.nums and Xl.nums.add)or 0.5,sold=0,ok=true,study=true,studyMax=2}
bb.pasExp={kind=URe[2558],id=Sl}
table.insert(Vl,Xl.name..URe[2746])
else
table.insert(Vl,Xl.name..URe[2717]..(pb.LOOK[Xl.family]or URe[2747]))
end
end
end
if#Vl>0 then
F.log(1,URe[2748],string.format(URe[2749],V.name(Sl),table.concat(Vl,URe[2750])))
end
end
function pb.letOther(Yl)
