return Yl.id~=Zl.id and not V.isFarm(Yl.id)
end
function pb.freeSlot(am)
if am.freed then
return false
end
local bm={}
for cm,dm in ipairs(bb.mine or{})do
local em=dm:FindFirstChild(URe[2431])
local fm=em and em:FindFirstChild(URe[2751])
if fm then
bm[fm.Value]=(bm[fm.Value]or 0)+1
end
end
for hm,im in ipairs(bb.team or{})do
if im.id~=am.id and not V.isFarm(im.id)and im.u and im.uuid and(bm[im.uuid]or 0)<V.cap(im.u)then
return false
end
end
am.freed=true
pcall(bb.sampleHelpers,true)
local jm,km={},{}
for lm,nm in pairs(bb.helperDealt or{})do
if nm.owner then
jm[nm.owner]=(jm[nm.owner]or 0)+(tonumber(nm.v)or 0)
end
end
for om,qm in ipairs(bb.mine or{})do
local rm=qm:FindFirstChild(URe[2431])
local um=rm and rm:FindFirstChild(URe[2752])
if um then
km[um.Value]=(km[um.Value]or 0)+1
end
end
local vm,wm,xm,ym
for zm,Am in ipairs(bb.mine or{})do
local Bm=Am:FindFirstChild(URe[2431])
local Cm=Bm and Bm:FindFirstChild(URe[2752])
local Dm=Cm and Cm.Value
if Dm and Dm~=am.id and not V.isFarm(Dm)and not V.allyBuff(Dm)then
local Em=Bm:FindFirstChild(URe[2753])
local Fm=type(bb.ownDealt)==URe[2359]and bb.ownDealt[Am]and tonumber(bb.ownDealt[Am].v)or 0
local Gm=math.max(Em and tonumber(Em.Value)or 0,Fm)+(jm[Dm]or 0)/math.max(1,km[Dm]or 1)
local Hm=V.rows(Dm)
local Im=tonumber(Hm and Hm[0]and Hm[0].cost)or math.huge
local Jm=Bm:FindFirstChild(URe[2462])
local Km=Jm and tonumber(Jm.Value)or 0
if not vm or Gm<wm or(Gm==wm and Im<xm)then
vm,wm,xm,ym=Am,Gm,Im,Km
end
end
end
if not vm then
F.log(1,URe[2748],string.format(URe[2754],V.name(am.id)))
return false
end
local Lm=V.name(vm._stats.id.Value)
local Mm,Nm=F.request(URe[2558],URe[2450],vm)
if Mm and Nm then
table.insert(bb.actions,URe[2755]..Lm..URe[2756])
F.log(1,URe[2748],string.format(URe[2757],V.name(am.id),Lm,ym or 0,U.fmt(wm or 0),V.name(am.id)))
return true
end
F.log(1,URe[2748],string.format(URe[2758],V.name(am.id),Lm,tostring(Nm)))
return false
end
function pb.nearCast(Om,Pm,Qm)
local Rm=0
for Sm,Tm in ipairs(Qm or{})do
for Um,Vm in ipairs(Om.casts)do
if Vm.id==Pm and Tm>=Vm.t-0.5 and Tm<=Vm.t+10 then
Rm=Rm+1
break
end
end
end
return Rm
end
function pb.watchIds()
local Wm,Xm={},0
if P.trial and P.trial.study and bb.trialId then
Wm[bb.trialId]=true
Xm=Xm+1
end
if O.pasWatch~=false then
for Ym,Zm in ipairs(bb.team or{})do
if not Wm[Zm.id]then
local _m,an=pcall(pb.guess,Zm.id)
for bn,cn in ipairs(_m and type(an)==URe[2359]and an or{})do
if cn.playable and not cn.hand and pb.sure(Zm.id,cn)~=URe[2737]then
Wm[Zm.id]=true
Xm=Xm+1
break
end
end
end
end
end
return Wm,Xm
end
function pb.newWatch()
local dn,en=pb.watchIds()
return{t0=U.now(),ids=dn,n=en,idsAt=U.now(),copies={},placed={},removed={},transforms={},own={},foe=setmetatable({},{__mode=URe[2759]}),foeBuffs={},meters={},steps={},deaths={},sumOf=setmetatable({},{__mode=URe[2759]}),summons={},casts={},castN={},sales=0,firstPlaced={},nearN=0}
end
function pb.tick()
local gn=bb.pas
if not gn then
gn=pb.newWatch()
bb.pas=gn
end
