local kn=U.now()-gn.t0
local ln={}
local mn={}
for nn,pn in ipairs(bb.mine or{})do
local qn=pn:FindFirstChild(URe[2431])
local rn=qn and qn:FindFirstChild(URe[2752])
if rn then
local un=rn.Value
ln[pn]=true
local vn=gn.copies[pn]
local wn=qn:FindFirstChild(URe[2462])
local xn=wn and tonumber(wn.Value)or 0
if not vn then
vn={id=un,at=kn,lvl=xn,sold=gn.sales,buff={},stat={}}
gn.copies[pn]=vn
if#gn.placed<200 then
table.insert(gn.placed,{t=kn,id=un,sold=gn.sales})
end
if gn.firstPlaced[un]==nil then
gn.firstPlaced[un]=kn
end
local yn=bb.pasExp
if type(yn)==URe[2359]and yn.kind==URe[2558]and un~=yn.id and gn.sales>0 and not V.isFarm(un)then
yn.otherDone=true
end
end
if vn.id~=un then
if#gn.transforms<20 then
table.insert(gn.transforms,{t=kn,from=vn.id,to=un})
end
vn.id=un
end
vn.lvl=math.max(vn.lvl,xn)
local zn=qn:FindFirstChild(URe[2761])
vn.max=zn and tonumber(zn.Value)or vn.max
local An=pn:FindFirstChild(URe[2762])
for Bn,Cn in ipairs(An and An:GetChildren()or{})do
local Dn=(Cn:IsA(URe[2763])and tonumber(Cn.Value))or 1
local En=Cn.Name
vn.buff[En]=math.max(vn.buff[En]or-math.huge,Dn)
if Dn>0 then
local Fn=gn.own[En]
if not Fn then
Fn={first=kn,last=kn,max=Dn,by={},vals={},starts={}}
gn.own[En]=Fn
end
Fn.last,Fn.max=kn,math.max(Fn.max,Dn)
Fn.by[un]=(Fn.by[un]or 0)+1
mn[En]=(mn[En]or 0)+1
if#Fn.vals<12 then
local Gn=math.floor(Dn*1000+0.5)/1000
local Hn=false
for In,Jn in ipairs(Fn.vals)do
if Jn==Gn then
Hn=true
break
end
end
if not Hn then
table.insert(Fn.vals,Gn)
end
end
end
end
if gn.ids[un]then
local Kn=qn:FindFirstChild(URe[2764])
vn.tk=Kn and tonumber(Kn.Value)or vn.tk
local Ln=qn:FindFirstChild(URe[2627])
vn.range=Ln and tonumber(Ln.Value)or vn.range
local Mn,Nn=pcall(function()
return pn:GetPivot().Position
end)
if Mn then
vn.pos=Nn
end
local On=0
for Pn,Qn in ipairs(qn:GetChildren())do
if Qn:IsA(URe[2765])or Qn:IsA(URe[2766])then
local Rn=Qn.Name
if not pb.STAT_SKIP[Rn]then
local Sn=tonumber(Qn.Value)
local Tn=vn.stat[Rn]
if Sn and(Tn or On<24)then
if not Tn then
Tn={lo=Sn,hi=Sn}
vn.stat[Rn]=Tn
On=On+1
end
Tn.lo,Tn.hi=math.min(Tn.lo,Sn),math.max(Tn.hi,Sn)
end
end
end
end
end
end
end
for Un,Vn in pairs(mn)do
local Wn=gn.own[Un]
if Wn and(gn.ownCnt and(gn.ownCnt[Un]or 0)or 0)==0 and#Wn.starts<40 then
table.insert(Wn.starts,kn)
end
end
gn.ownCnt=mn
for Xn,Yn in pairs(gn.copies)do
if not ln[Xn]and not Yn.gone then
Yn.gone=kn
local Zn=Yn.max~=nil and Yn.lvl>=Yn.max
if#gn.removed<100 then
table.insert(gn.removed,{t=kn,id=Yn.id,lvl=Yn.lvl,atMax=Zn or nil})
end
if Zn and gn.ids[Yn.id]then
gn.sales=gn.sales+1
gn.lastSale=kn
end
