function pb.evidence(cp,dp,ep)
local fp=type(ep.nums)==URe[2359]and ep.nums or{}
local ip=cp.firstPlaced[dp]
if not ip then
return{why=URe[2770]}
end
local jp={}
for kp,lp in ipairs(ep.buffs or{})do
jp[lp]=true
end
local function mp(np)
if#np==0 then
return nil
end
table.sort(np)
return np[math.ceil(#np/2)]
end
if ep.family==URe[2558]then
if(cp.sales or 0)==0 then
return{why=URe[2771]}
end
local op,pp
for qp in pairs(cp.own)do
local rp,vp,wp,yp,zp=0,0,0,0,0
for Ap,Bp in pairs(cp.copies)do
local Cp=Bp.buff[qp]or 0
if(Bp.sold or 0)>0 then
if Bp.id~=dp then
yp=yp+1
end
if Cp>0 then
if Bp.id==dp then
rp=rp+1
else
wp=wp+1
end
zp=math.max(zp,Cp)
end
elseif Cp>0 then
vp=vp+1
end
end
if rp>0 and vp==0 and(not pp or rp>pp)then
op,pp={name=qp,other=wp,otherAfter=yp,top=zp},rp
end
end
if not op then
return{why=URe[2772]}
end
local Dp=(op.other>0 and URe[1289])or(op.otherAfter>0 and URe[2773])or URe[2774]
return{seen=true,buff=op.name,who=Dp,nums={stacks=(cp.sales>1 and op.top>1)or nil,sales=cp.sales},why=string.format(URe[2775],pp,op.name,Dp==URe[2773]and URe[2776]or URe[1278])}
end
local Ep=ep.trigger and tostring(ep.trigger):find(URe[2777],1,true)~=nil
local Fp=0
for Gp,Hp in ipairs(cp.casts)do
if Hp.id==dp then
Fp=Fp+1
end
end
if Ep and Fp==0 and(ep.family==URe[2559]or ep.family==URe[2556])then
return{why=URe[2778]}
end
if ep.family==URe[2559]then
local Ip,Jp,Kp
for Lp,Mp in pairs(cp.own)do
if Mp.first>=ip-1 and(jp[Lp]or Mp.first<=ip+5 or Ep)and(not Ep or pb.nearCast(cp,dp,Mp.starts)>0)then
local Np=0
for Op,Pp in pairs(Mp.by)do
if Op~=dp then
Np=Np+Pp
end
end
if Np>0 and(not Ip or(jp[Lp]and not Kp)or((jp[Lp]or false)==(Kp or false)and Np>Jp))then
Ip,Jp,Kp=Lp,Np,jp[Lp]
end
end
end
if not Ip then
return{why=URe[2779]}
end
return{seen=true,buff=Ip,why=string.format(URe[2780],Ip)}
end
if ep.family==URe[2556]then
local Qp,Rp
for Sp,Tp in pairs(cp.foeBuffs)do
if Tp.first>=ip-1 and Tp.near>0 and(jp[Sp]or Tp.near>=0.5*Tp.n)and(not Ep or pb.nearCast(cp,dp,Tp.onsets)>0)then
local Vp=Tp.near+(jp[Sp]and 1e6 or 0)+(Ep and pb.nearCast(cp,dp,Tp.onsets)*1000 or 0)
if not Rp or Vp>Rp then
Qp,Rp=Sp,Vp
end
end
end
if not Qp then
return{why=URe[2781]}
end
local Wp=cp.foeBuffs[Qp]
local Xp={}
if#Wp.durs>=3 then
Xp.secsSeen=math.floor(mp(Wp.durs)*10+0.5)/10
elseif Wp.foes>=5 then
Xp.keepSeen=true
end
if Wp.spN>=5 then
local Yp=Wp.sp/Wp.spN
if Yp<0.97 then
Xp.slowSeen=math.floor((1-Yp)*100+0.5)/100
end
end
if fp.chance and(cp.nearN or 0)>0 then
Xp.chanceSeen=math.floor(math.min(1,Wp.foes/cp.nearN)*100+0.5)/100
end
Xp.bossToo=Wp.boss>0 or nil
return{seen=true,buff=Qp,nums=Xp,why=string.format(URe[2782],Wp.foes,Qp)}
end
if ep.family==URe[2613]then
local Zp=(tonumber(fp.below)or 0.25)+0.02
local _p,aq=0,0
for bq,cq in ipairs(cp.deaths)do
if not cq.boss then
aq=aq+1
if cq.frac>0.04 and cq.frac<=Zp then
_p=_p+1
end
end
end
if aq<10 then
return{why=URe[2783]}
end
local dq=_p/aq
if dq<0.3 then
return{why=string.format(URe[2784],math.floor(dq*100))}
end
return{seen=true,nums={shareSeen=math.floor(dq*100+0.5)/100},why=string.format(URe[2785],_p,aq,math.floor(Zp*100))}
end
if ep.family==URe[2457]then
local eq={}
for fq,gq in ipairs(cp.summons)do
if gq.owner==dp then
table.insert(eq,gq)
end
end
if#eq<2 then
return{why=URe[2786]}
end
table.sort(eq,function(hq,iq)
return hq.born<iq.born
end)
local jq,kq,lq={},{},{}
for mq=2,#eq do
local nq=(eq[mq].tk or 0)-(eq[mq-1].tk or 0)
if nq>0 then
table.insert(jq,nq)
end
end
for oq,pq in ipairs(eq)do
if pq.died then
table.insert(kq,pq.died-pq.born)
end
table.insert(lq,{pq.born,1})
table.insert(lq,{pq.died or pq.last or pq.born,-1})
end
table.sort(lq,function(qq,rq)
return qq[1]<rq[1]
end)
local sq,tq=0,0
for uq,vq in ipairs(lq)do
sq=sq+vq[2]
tq=math.max(tq,sq)
end
local wq=mp(kq)
return{seen=true,nums={everySeen=mp(jq),lifeSeen=wq and math.floor(wq+0.5)or nil,capSeen=tq,made= #eq},why=string.format(URe[2787],#eq)}
end
if ep.family==URe[2560]then
local xq,yq
for zq,Aq in pairs(cp.own)do
if(Aq.by[dp]or 0)>0 and Aq.first>=ip-1 and(not xq or(jp[zq]and not jp[xq]))then
xq,yq=zq,Aq
end
end
local Bq
for Cq,Dq in ipairs(cp.transforms)do
if Dq.from==dp then
Bq=Dq.to
end
end
if not xq then
local Eq,Fq,Gq
for Hq,Iq in pairs(cp.copies)do
if Iq.id==dp or(Bq and Iq.id==Bq)then
for Jq,Kq in pairs(Iq.stat or{})do
if Kq.hi>Kq.lo and(not Eq or(Kq.hi-Kq.lo)>(Gq-Fq))then
Eq,Fq,Gq=Jq,Kq.lo,Kq.hi
end
end
end
end
if not Eq then
return{why=URe[2788]}
end
