function pb.model(Zr,as,bs)
local cs=tostring(Zr)..URe[2501]..tostring(bs and bs.atk)..URe[2501]..tostring(bs and bs.cd)
local ds=pb._model[cs]
if ds~=nil then
return ds or nil
end
local es,fs={},false
local gs=math.max(0.3,tonumber(bs and bs.cd)or 2)
local hs=math.min(1,(tonumber(as and as.n)or 1)/4)
local js,ks=pcall(pb.guess,Zr)
local ls,ms={},{}
for ns,ps in ipairs(js and type(ks)==URe[2359]and ks or{})do
if ps.hand then
ls[ps.pid]=true
end
ms[ps.pid]=ps.nums
end
for qs,rs in pairs(pb.rules(Zr))do
if not ls[qs]then
local ss={}
for ts,us in pairs(type(ms[qs])==URe[2359]and ms[qs]or{})do
ss[ts]=us
end
for vs,ws in pairs(type(rs.nums)==URe[2359]and rs.nums or{})do
ss[vs]=ws
end
local xs=rs.trigger~=nil and tostring(rs.trigger):find(URe[2777],1,true)~=nil
if rs.family==URe[2559]then
