local zs=es.aura or{typed={}}
for As,Bs in pairs(type(ss.typed)==URe[2359]and ss.typed or{})do
zs.typed[As]=math.max(zs.typed[As]or 0,(tonumber(Bs)or 0)*ys)
end
local Cs=tonumber(ss.dmgMax)or tonumber(ss.dmg)
if Cs then
zs.dmg=math.max(zs.dmg or 0,Cs*ys)
end
if ss.crit then
zs.crit=math.max(zs.crit or 0,(tonumber(ss.crit)or 0)*ys)
end
es.aura,fs=zs,true
elseif rs.family==URe[2556]then
local Ds=pb.KW[tostring(rs.keyword or URe[1278])]
local Es=tonumber(ss.chance)or 1
local Fs=tonumber(ss.secsSeen)or tonumber(ss.secs)or 5
local Gs=ss.keep or ss.keepSeen
local Hs=Gs and math.min(1,Es*4)or math.min(1,Fs*Es/gs)
if xs then
Hs=math.min(Hs,Fs/60)
end
if Ds and Ds.kind==URe[2546]and not(type(ss.shred)==URe[2359])then
local Is=tonumber(ss.amp)
local Js=as and((type(as.ampTypes)==URe[2359]and as.ampTypes[Ds.dtype])or(tonumber(as.amp)or 0)>0)
if Is and Is>0 and not Js then
es.fx,fs=(es.fx or 0)+Is*V.TYPED_AMP_SHARE*Hs*hs,true
end
elseif Ds and(Ds.kind==URe[2494]or Ds.kind==URe[2554])then
if not(as and((tonumber(as.stun)or 0)>0 or(tonumber(as.slowTime)or 0)>0))then
es.stun=(Ds.kind==URe[2554]and 0.5 or 1)*Fs
if ss.slow then
es.slowP,es.slowT=tonumber(ss.slow),Fs
end
fs=true
end
elseif Ds and Ds.kind==URe[2496]then
if not(as and(tonumber(as.slowTime)or 0)>0)then
es.slowP,es.slowT,fs=tonumber(ss.slow)or tonumber(ss.slowSeen)or 0.3,Fs,true
end
elseif Ds and Ds.kind==URe[2553]then
local Ks=tonumber(ss.dot)or 0
if Ks>0 and(tonumber(as and as.dot)or 0)<Ks*0.5 then
local Ls=math.min(1.5,Ks)*Es
es.dot,fs=(es.dot or 0)+Ls,true
if tostring(rs.keyword)==URe[2201]then
es.burnDot=(es.burnDot or 0)+Ls
end
end
end
if type(ss.ampFrom)==URe[2359]and tostring(ss.ampFrom.kind)==URe[2201]and(tonumber(ss.ampFrom.amp)or 0)>0 then
local Ms=(type(ss.secsBy)==URe[2359]and#ss.secsBy>0)and ss.secsBy or{tonumber(ss.secsSeen)or tonumber(ss.secs)or 5}
es.flames,fs={amp=tonumber(ss.ampFrom.amp),secs=Ms},true
