end
if CE.ice>0 then
local GE=bb.rogueShare(URe[2510])
DE=DE*(GE+(1-GE)/(1-CE.ice+CE.ice/gb.modFactor(URe[2918])))
end
if CE.fly>0 then
DE=DE*(1-CE.fly*0.5)
end
if CE.noCC then
DE=DE*0.95
end
if CE.shroud then
DE=DE*0.9
end
if CE.zap then
DE=DE*0.85
end
return DE/mb.weatherK(BE)
end
