table.insert(Djb,{kind=URe[3500],uuid=Kjb,name=Njb,gain=Sjb,add=Pjb,planned=Tjb.planned,items=Tjb.n,lvl0=Ujb,lvl1=kb.level({unit_id=Mjb,xp=(tonumber(Ljb.xp)or 0)+(Tjb.planned>0 and Tjb.planned or Pjb)}),text=string.format(URe[3501],Njb,U.fmt(Pjb),Vjb>Ujb and string.format(URe[3502],Ujb,Vjb)or string.format(URe[3503],Ujb),Sjb)})
end
end
end
end
table.sort(Djb,function(Wjb,Xjb)
