function kb.xpRate()
local akb=N.session()
if not akb then
return 0
end
local bkb=0
for ckb,dkb in ipairs(kb.core())do
local ekb=akb.collection:get_unit_by_uuid(dkb)
if ekb then
local fkb,gkb=kb.gainXp(ekb,500000)
if gkb>0 then
bkb=math.max(bkb,fkb/gkb)
end
end
end
local hkb=bkb*(O.strengthValue or 300)
if(tonumber(N.cur(URe[2434]))or 0)>(O.xpGoldFloor or 100000)then
hkb=math.min(hkb,(N.GOLD_VALUE or 0.02)/14)
