function kb.xpGuess(ikb)
local jkb=ikb.level and N.Levels[ikb.level]
if not jkb then
return 0
end
local kkb=math.min(9,tonumber(jkb.story_world_rank)or tonumber(ikb.rank)or 9)
local lkb=tonumber(jkb.story_level_rank)or 6
local mkb=(ikb.kind==URe[2408]and 1.5 or 1)*(kkb>5 and 2 or 1)
local nkb=2.1564^(kkb-1)*(40+10*lkb)/mkb
if ikb.kind==URe[2384]then
nkb=3*30*2.1564^(kkb-1)/mkb
end
local okb=kkb>=9 and 0.3 or(kkb>=7 and 0.5 or 1)
