function kb.feedPlan(Ekb)
local Fkb=V.trait(Ekb)
local Gkb=Fkb==URe[3506]and 1.5 or 1
local Hkb=math.max(0,kb.xpFor(Ekb.unit_id,kb.cap(Ekb))-(tonumber(Ekb.xp)or 0))
local Ikb,Jkb,Kkb={},0,0
for Lkb,Mkb in ipairs(kb.foodHeld())do
local Nkb=Mkb.xp*Gkb
local Okb=math.min(Mkb.n,math.floor((Hkb-Jkb)/math.max(1,Nkb)))
if Okb>0 then
Ikb[Mkb.id]=Okb
Jkb=Jkb+Okb*Nkb
Kkb=Kkb+Okb
end
end
return{feed=Ikb,planned=Jkb,n=Kkb}
end
function kb.run(Pkb)
