cb.add(string.format(URe[3509],Vkb,Pkb.name),Vkb,URe[3510],string.format(URe[3511],U.fmt(blb),dlb))
kb.note(string.format(URe[3512],Pkb.name,Vkb,U.fmt(blb),dlb,math.abs(blb-Ukb)>Ukb*0.1 and string.format(URe[3513],U.fmt(Ukb))or URe[1278]))
