end
F.log(1,URe[3000],string.format(URe[3903],WBb,#iCb>0 and(URe[3904]..table.concat(iCb,URe[2483]))or URe[3905],gCb and(URe[3906]..tostring(gCb))or URe[1278]))
W.lastScored=nil
