if not RHb[XHb]and not RHb[ZHb]and N.Units[ZHb]and not V.isFarm(ZHb)and not V.allyBuff(ZHb)and os.time()-(tonumber(OHb.tried[ZHb])or 0)>ab.LAB.AGAIN and(tonumber(type(OHb.blank)==URe[2359]and OHb.blank[ZHb])or 0)<ab.LAB.BLANKS then
