end
local pIb,qIb=pcall(gb.run,lIb,gb.teamFrom(mIb,lIb.map),{hpMul=1.1})
local rIb=pIb and type(qIb)==URe[2359]and(qIb.won or(lIb.infinite and(tonumber(qIb.wave)or 0)>=0.8*W.infReach(NHb.key)))
if not rIb then
