function ab.partyChase(XKb,YKb)
local ZKb,_Kb=U.now(),-999
while F.alive and U.now()-ZKb<(YKb or 75)do
local aLb=U.now()-_Kb>=15
if aLb then
_Kb=U.now()
end
local bLb,cLb,dLb=ab.partyFind(XKb,aLb)
if cLb then
return ab.partyGo(bLb,cLb,dLb)
end
task.wait(2)
end
return false
end
ab.PARTY_START={delay=3,gap=5,tries=3}
function ab.partyStart()
if ab.partyRole()~=URe[4064]or O.partyStart==false then
ab.PARTY.room=nil
return false
end
local eLb,fLb=ab.partyHost()
if not(eLb and fLb)then
ab.PARTY.room=nil
return false
end
local gLb=N.svc(URe[3984])
local hLb=gLb and gLb.current_lobby
if hLb==nil or hLb==URe[1278]then
ab.PARTY.room=nil
return false
end
local iLb=ab.PARTY.room
if not iLb or iLb.name~=tostring(hLb)then
iLb={name=tostring(hLb),at=U.now(),tries=0,last= -999}
ab.PARTY.room=iLb
end
local jLb=ab.PARTY_START
if U.now()-iLb.at<jLb.delay or iLb.tries>=jLb.tries or U.now()-iLb.last<jLb.gap then
return false
end
iLb.tries,iLb.last=iLb.tries+1,U.now()
local kLb,lLb=F.request(URe[4092],URe[3947],hLb)
F.log(iLb.tries==1 and 1 or 2,URe[4072],string.format(URe[4093],tostring(kLb and lLb),iLb.tries>1 and string.format(URe[4094],iLb.tries,jLb.tries)or URe[1278]))
return true
end
