function ab.updateCheck()
local tLb=tostring((N.GS or{}).CURRENT_UPDATE or URe[2610])
P.gameSeen=type(P.gameSeen)==URe[2359]and P.gameSeen or{}
local uLb=P.gameSeen
if uLb.update~=tLb then
if uLb.update and uLb.update~=URe[2610]and tLb~=URe[2610]then
F.log(1,URe[4120],string.format(URe[4121],tostring(uLb.update),tLb))
if F.notify then
F.notify(URe[4122],URe[4123]..tLb..URe[4124],URe[3590])
end
end
uLb.update,uLb.at,uLb.places,uLb.remotes,uLb.said=tLb,os.time(),{},{},{}
end
uLb.places=type(uLb.places)==URe[2359]and uLb.places or{}
uLb.remotes=type(uLb.remotes)==URe[2359]and uLb.remotes or{}
uLb.said=type(uLb.said)==URe[2359]and uLb.said or{}
uLb.places[F.where]=true
local vLb=I:FindFirstChild(URe[2443])and I.endpoints:FindFirstChild(URe[4125])
for wLb,xLb in ipairs(N.REMOTES)do
if vLb and vLb:FindFirstChild(xLb)then
uLb.remotes[xLb]=true
end
end
local yLb={}
for zLb,ALb in ipairs({URe[2422],URe[2423],URe[2426],URe[2427],URe[2425]})do
if type(N[ALb])~=URe[2359]or next(N[ALb])==nil then
table.insert(yLb,ALb)
end
end
if#yLb>0 and not uLb.said._data then
uLb.said._data=true
F.log(1,URe[4120],URe[4126]..table.concat(yLb,URe[2483])..URe[4127])
end
if uLb.places.lobby and uLb.places.match then
local BLb={}
for CLb,DLb in ipairs(N.REMOTES)do
if not uLb.remotes[DLb]and not uLb.said[DLb]then
uLb.said[DLb]=true
table.insert(BLb,DLb)
end
end
if#BLb>0 then
F.log(1,URe[4120],URe[4128]..table.concat(BLb,URe[2483])..URe[4129])
end
end
if F.where==URe[2439]and not uLb.said._locked and type(P.cleared)==URe[2359]then
local ELb,FLb=0,0
for GLb in pairs(P.cleared)do
local HLb=tostring(GLb):match(URe[4130])
if HLb and N.Levels[HLb]then
ELb=ELb+1
local ILb,JLb=pcall(W.open,HLb)
if ILb and JLb==false then
FLb=FLb+1
end
if ELb>=5 then
break
end
end
end
if ELb>=3 and FLb==ELb then
uLb.said._locked=true
F.log(1,URe[4120],string.format(URe[4131],FLb))
end
end
end
