function eb.upgradeGain(CNb,DNb,ENb,FNb,GNb,HNb)
local INb,JNb=DNb[ENb],DNb[ENb+1]
local KNb=(INb.cd>0 and INb.damage/INb.cd or 0)
local LNb=(JNb.cd>0 and JNb.damage/JNb.cd or 0)*V.aoe(JNb.atk,JNb.range)/math.max(0.3,V.aoe(INb.atk,INb.range))
local MNb=KNb>0 and CNb*(LNb/KNb-1)or(HNb or 0)
local NNb=DNb[ENb+2]
if NNb and ENb+1<DNb.max and NNb.cd>0 and JNb.cd>0 and KNb>0 then
local ONb=CNb*((NNb.damage/NNb.cd)/KNb-1)
local PNb=FNb+NNb.cost*GNb
if ONb/PNb>MNb/FNb then
MNb=MNb+(ONb/PNb*FNb-MNb)*0.5
end
end
local QNb=(JNb.range or 0)>(INb.range or 0)and(1+((JNb.range-INb.range)/math.max(1,INb.range)))or 1
return math.max(0,MNb)*QNb
end
function eb.dpsFor(RNb,SNb)
if SNb<=0 then
return 0
end
local TNb={}
for UNb,VNb in ipairs(RNb)do
if not VNb.farm and not VNb.grif and VNb.gain>0 then
table.insert(TNb,VNb)
end
end
table.sort(TNb,function(WNb,XNb)
return WNb.gain/WNb.cost>XNb.gain/XNb.cost
end)
local YNb,ZNb=0,0
for _Nb,aOb in ipairs(TNb)do
if SNb<=0 then
break
end
ZNb=aOb.gain/aOb.cost
local bOb=math.min(1,SNb/aOb.cost)
YNb=YNb+aOb.gain*bOb
SNb=SNb-aOb.cost*bOb
end
return YNb+math.max(0,SNb)*ZNb*0.7
end
function eb.shieldDps(cOb,dOb,eOb,fOb,gOb,hOb,iOb)
if(fOb or 0)<=0 or(cOb or 0)<=0 or(gOb or 0)<=0 then
return cOb or 0
end
dOb,eOb,hOb=math.max(0.3,dOb or 2),math.max(1,eOb or 1),hOb or 1
local jOb=cOb*hOb*dOb/eOb
return gOb*eOb/((fOb/math.max(1,iOb or 1)+math.max(1,gOb/jOb))*dOb)/hOb
end
function eb.shieldGain(kOb,lOb,mOb,nOb,oOb,pOb,qOb,rOb)
local sOb,tOb=V.attackInfo(lOb.atk,lOb.range),V.attackInfo(nOb.atk,nOb.range)
local uOb=eb.shieldDps(kOb,(tonumber(lOb.cd)or 2)*(qOb or 1),sOb.n,oOb,pOb,rOb,sOb.hits)
