end
if Npc.strong and Npc.strong[jqc]then
table.insert(Wpc,string.format(URe[4366],Lpc(jqc)))
end
if#Wpc==0 then
table.insert(Wpc,URe[4367])
end
local oqc,pqc,qqc=pcall(V.mapNudge,Vpc,Jpc and Jpc.map,Jpc and Jpc.mapSig)
local rqc=oqc and type(qqc)==URe[2359]and(tonumber(qqc.n)or 0)or 0
