for zxc,Axc in ipairs(qxc)do
local Bxc=jb.roomValue(Axc,pxc)
local Cxc,Dxc
for Exc,Fxc in ipairs(jb.after(mxc,Axc.choice))do
local Gxc=jb.roomValue(Fxc,pxc)
if not Cxc or Gxc>Cxc then
Cxc,Dxc=Gxc,Fxc
end
end
