vxc=Axc
end
if Jxc then
if not yxc or Axc.score>yxc.score then
yxc=Axc
end
elseif not xxc or Axc.score>xxc.score then
xxc=Axc
end
end
if not wxc or Axc.score>wxc.score then
wxc=Axc
end
end
