if not(Dzc or Izc>=jb.ROOMS or Hzc<=1)then
jb.note(string.format(URe[4525],Izc,Fzc,Gzc,jb.luck(Czc)))
F.request(URe[4512],URe[4513])
return
end
local Jzc,Kzc,Lzc=0,0,0
local Mzc=tonumber(N.cur(URe[2432]))or 0
local Nzc=jb.wallet()
for Ozc=1,Fzc+Gzc+4 do
local Pzc,Qzc,Rzc=jb.res(jb.data())
if Qzc+Rzc<=0 or Lzc>=2 then
break
end
local Szc,Tzc
if Qzc>0 then
Szc,Tzc=F.request(URe[4526],URe[4108])
else
Szc,Tzc=F.request(URe[4526],URe[4108],true)
end
if Szc and Tzc~=nil then
F.log(1,URe[4490],URe[4527]..(type(Tzc)==URe[2359]and U.json(U.plain(Tzc)):sub(1,300)or tostring(Tzc)))
end
local Uzc=U.now()
while U.now()-Uzc<4 do
local Vzc,Wzc,Xzc=jb.res(jb.data())
if Wzc<Qzc or Xzc<Rzc then
break
end
task.wait(0.25)
end
local Yzc,Zzc,_zc=jb.res(jb.data())
if Zzc<Qzc then
Jzc=Jzc+(Qzc-Zzc)
Lzc=0
elseif _zc<Rzc then
Kzc=Kzc+(Rzc-_zc)
Lzc=0
else
Lzc=Lzc+1
end
task.wait(1)
if Zzc<Qzc or _zc<Rzc then
local aAc=jb.wallet()
local bAc=jb.walletDiff(Nzc,aAc)
F.log(1,URe[4490],(_zc<Rzc and URe[4528]or URe[4527])..bAc)
P.dg.pay=P.dg.pay or{}
local cAc={}
for dAc,eAc in pairs(aAc.items)do
if eAc~=(Nzc.items[dAc]or 0)then
cAc[dAc]=eAc-(Nzc.items[dAc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=_zc<Rzc,gems=aAc.gems-Nzc.gems,luck=jb.luck(Czc),paid=bAc,items=cAc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
Nzc=aAc
end
end
jb.note(string.format(URe[4529],Jzc,Kzc,Dzc and URe[4530]or(Hzc<=1 and URe[4531]or URe[4532]),jb.luck(Czc),(tonumber(N.cur(URe[2432]))or 0)-Mzc))
local fAc,gAc,hAc=jb.res(jb.data())
if(Dzc or Izc>=jb.ROOMS)and gAc+hAc>0 then
jb.note(string.format(URe[4533],gAc,hAc))
W.rec(URe[3130]).restUntil=os.time()+1800
return URe[4534]
end
if not Dzc then
F.request(URe[4512],URe[4513])
end
end
function jb.act(iAc)
local jAc,kAc=jb.state(iAc)
jb.logState(iAc,jAc)
if jAc==URe[4497]then
return false
end
if jAc==URe[4496]then
jb.note(string.format(URe[4535],tostring(kAc and kAc.t)))
F.request(URe[4512],URe[4513])
return true
end
if jAc==URe[3174]then
F.request(URe[4536],URe[4106])
jb.note(URe[4537])
P.dg.lives,P.dg.lost,P.dg.bailed,P.dg.bails=5,{},{},{}
elseif jAc==URe[4494]then
if jb.openChests(iAc,true)==URe[4534]then
return URe[4534]
end
F.request(URe[4512],URe[4513])
local lAc,mAc,nAc=jb.res(jb.data())
table.insert(P.dg.runs,1,{at=os.time(),depth=jb.ROOMS,items=U.count(jb.items(iAc)),left=mAc+nAc})
while#P.dg.runs>10 do
table.remove(P.dg.runs)
end
jb.note(URe[4538])
elseif jAc==URe[3534]then
jb.shop(iAc,kAc)
elseif jAc==URe[4447]then
jb.shrine(iAc,kAc)
elseif jAc==URe[4495]then
if jb.openChests(iAc,false)==URe[4534]then
return URe[4534]
end
end
return true
end
function jb.launch(oAc)
local pAc=jb.data()
if not pAc then
F.backoff(URe[3914],30)
return false
end
if not pAc._started then
if not(O.dungeonStart or O.onlyDungeons)then
return false
end
local qAc,rAc=F.request(URe[4539],URe[4110])
task.wait(2.5)
pAc=jb.data()
if not(qAc and pAc and pAc._started)then
F.log(1,URe[4490],URe[4540]..tostring(rAc)..URe[4541])
W.rec(URe[3130]).restUntil=os.time()+1800
F.backoff(URe[3914],10)
return false
end
P.dg.lost,P.dg.bailed,P.dg.bails={},{},{}
jb.note(URe[4542])
end
if jb.enter(pAc,oAc.value,false)then
return true
end
F.backoff(URe[3914],10)
return false
end
function jb.playLast()
local sAc=P.dg.playLast
return type(sAc)==URe[2359]and os.time()-(tonumber(sAc.at)or 0)<1800 and sAc or nil
end
function jb.forced(tAc)
local uAc=P.dg.force
if type(uAc)~=URe[2359]or type(uAc.uuids)~=URe[2359]or uAc.seed~=tostring(tAc.r._r)then
return nil
end
if os.time()-(tonumber(uAc.at)or 0)>3600 then
P.dg.force=nil
return nil
end
return uAc
end
function jb.startTeam(vAc,wAc,xAc,yAc)
P.startTeam={uuids=table.clone(vAc),must=true,own=yAc or nil,seed=tostring(wAc.r._r),why=xAc}
end
function jb.weakMatch(zAc,AAc)
local BAc,CAc=pcall(V.types,zAc)
if not BAc or type(CAc)~=URe[2359]then
return false
end
for DAc,EAc in pairs(CAc)do
local FAc=type(DAc)==URe[2360]and EAc or DAc
if AAc[FAc]then
return true
end
end
return false
end
function jb.fasterTeam(GAc,HAc,IAc,JAc,KAc)
local LAc=U.now()
local function MAc(NAc)
local OAc=gb.run(GAc,gb.teamFrom(NAc,GAc.map),{hpMul=1})
return OAc and OAc.won and tonumber(OAc.t)or nil
end
local PAc=MAc(HAc)
if not PAc then
return nil
end
local QAc={}
for RAc,SAc in ipairs(HAc)do
QAc[SAc.unit_id]=true
end
local TAc={}
for UAc,VAc in ipairs(IAc)do
if#TAc>=6 then
break
end
if not QAc[VAc.unit_id]and not V.isFarm(VAc.unit_id)and not V.allyBuff(VAc.unit_id)and jb.weakMatch(VAc.unit_id,JAc)then
QAc[VAc.unit_id]=true
table.insert(TAc,VAc)
end
end
if#TAc==0 then
return nil
end
local WAc,XAc,YAc=table.clone(HAc),PAc,{}
local ZAc=gb.lockIds()
for _Ac,aBc in ipairs(HAc)do
if U.now()-LAc>KAc then
break
end
if not ZAc[aBc.unit_id]and not V.isFarm(aBc.unit_id)and not V.allyBuff(aBc.unit_id)and not jb.weakMatch(aBc.unit_id,JAc)then
local bBc,cBc
for dBc,eBc in ipairs(TAc)do
if U.now()-LAc>KAc then
break
end
if not YAc[eBc.uuid]then
local fBc=table.clone(WAc)
fBc[_Ac]=eBc
local gBc=MAc(fBc)
if gBc and gBc<(cBc or XAc)then
bBc,cBc=eBc,gBc
end
end
end
if bBc then
WAc[_Ac]=bBc
YAc[bBc.uuid]=true
XAc=cBc
end
task.wait()
end
end
if XAc<PAc then
return WAc,PAc,XAc
end
return nil
end
function jb.planTeam(hBc,iBc,jBc)
if not(O.sim and O.simTeams)or type(hBc.r._l)~=URe[2359]then
return
end
if jb.playLast()then
F.log(1,URe[4231],string.format(URe[4543],hBc.d))
return
end
local kBc=jb.forced(hBc)
if kBc then
if jBc then
F.log(1,URe[4231],string.format(URe[4544],hBc.d,tostring(kBc.label)))
if not ib.same(ib.team(),kBc.uuids)then
jb.startTeam(kBc.uuids,hBc,tostring(kBc.label))
end
return
end
F.log(1,URe[4231],string.format(URe[4545],hBc.d,tostring(kBc.label)))
ab.equipTeam(kBc.uuids,tostring(kBc.label))
task.wait(0.5)
return
end
if jBc and not O.autoTeam then
return
end
local lBc=P.simTeam.dg
if not jBc and O.autoTeam and lBc and lBc.better and not lBc.stale and lBc.seed==tostring(hBc.r._r)and os.time()-(tonumber(lBc.at)or 0)<300 then
ab.equipTeam(lBc.uuids,URe[4546]..hBc.d)
