local EBc=type(P.dg.lost)==URe[2359]and P.dg.lost[tostring(hBc.r._r)]and P.dg.lost[tostring(hBc.r._r)][CBc]or 0
local FBc=type(P.dg.bailed)==URe[2359]and type(P.dg.bailed[tostring(hBc.r._r)])==URe[2359]and tonumber(P.dg.bailed[tostring(hBc.r._r)][CBc])or 0
EBc=EBc+FBc
local GBc,HBc,IBc,JBc=gb.strength(BBc.info,ABc)
local KBc=math.clamp((tonumber(DBc.w)or 0)-2*(tonumber(DBc.l)or 0),-6,3)
if hBc.d>=13 then
KBc=math.min(KBc,1)
end
KBc=KBc-3*EBc
local LBc=yBc and type(yBc.lost)==URe[2359]and yBc.lost[BBc.style]or nil
if type(LBc)==URe[2359]and LBc.sig==CBc then
KBc=KBc-3
end
return{score=GBc+KBc,wins=GBc,atOne=HBc,reach=IBc,far=JBc,lostHere=EBc,left=FBc,w=tonumber(DBc.w)or 0,l=tonumber(DBc.l)or 0,style=BBc.style}
end
local function MBc(NBc)
for OBc,PBc in ipairs(xBc)do
if PBc.style==NBc then
return PBc
