gb.explainSave(URe[3130],string.format(URe[4553],hBc.d,kCc and tostring(lCc)or URe[2610]),vBc,bCc,{jCc..URe[4554]},true,nBc,{won=true,wave=vBc.total,total=vBc.total,steps=eCc.wins,mySteps=ZBc.wins,realW=eCc.w,realL=eCc.l})
