function bb.buildPath()
bb.samples={}
local mFc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not mFc then
return
end
for nFc,oFc in pairs(mFc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[nFc.Name])then
local pFc={}
for qFc,rFc in ipairs(oFc.points or{})do
table.insert(pFc,rFc.part.Position)
end
local sFc=0
for tFc=2,#pFc do
sFc=sFc+(pFc[tFc]-pFc[tFc-1]).Magnitude
end
local uFc=0
for vFc=2,#pFc do
local wFc,xFc=pFc[vFc-1],pFc[vFc]
local yFc=(xFc-wFc).Magnitude
local zFc=math.max(1,math.floor(yFc/2))
for AFc=0,zFc-1 do
local BFc=wFc:Lerp(xFc,AFc/zFc)
table.insert(bb.samples,{pos=BFc,prog=(uFc+yFc*AFc/zFc)/math.max(1,sFc),lane=nFc.Name})
end
uFc=uFc+yFc
end
if pFc[#pFc]then
table.insert(bb.samples,{pos=pFc[#pFc],prog=1,lane=nFc.Name})
end
end
end
pcall(bb.readHidden,mFc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local CFc=tonumber(bb.ld and bb.ld._portal_lanes)
local DFc=gb.laneList(bb.samples)
if CFc and CFc>=1 and DFc and#DFc>CFc then
bb.laneWant=CFc
end
bb.laneTotal=DFc and#DFc or 1
bb.countLanes()
end
function bb.readHidden(EFc)
local FFc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(FFc)~=URe[2359]or not next(FFc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local GFc
for HFc,IFc in pairs(EFc)do
if FFc[HFc.Name]and type(IFc.points)==URe[2359]and#IFc.points>=2 then
local JFc={}
for KFc,LFc in ipairs(IFc.points)do
JFc[KFc]=U.flat(LFc.part.Position)
end
local MFc={}
for NFc,OFc in ipairs(bb.samples)do
local PFc=tostring(OFc.lane)
MFc[PFc]=MFc[PFc]or{}
table.insert(MFc[PFc],OFc)
end
local QFc,RFc
for SFc,TFc in pairs(MFc)do
local UFc=0
for VFc=1,#JFc,math.max(1,math.floor(#JFc/20))do
local WFc=math.huge
for XFc,YFc in ipairs(TFc)do
local ZFc=(U.flat(YFc.pos)-JFc[VFc]).Magnitude
if ZFc<WFc then
WFc=ZFc
end
end
UFc=UFc+WFc
end
if not RFc or UFc<RFc then
QFc,RFc=SFc,UFc
end
end
local _Fc,aGc,bGc,cGc,dGc,eGc={},nil,nil,nil,0,0
for fGc,gGc in ipairs(JFc)do
local hGc,iGc=nil,math.huge
for jGc,kGc in ipairs(MFc[QFc])do
local lGc=(U.flat(kGc.pos)-gGc).Magnitude
if lGc<iGc then
iGc,hGc=lGc,kGc.prog
end
end
eGc=math.max(eGc,iGc)
if bGc then
local mGc=hGc-bGc
local nGc=(mGc>0.002 and 1)or(mGc< -0.002 and-1)or cGc
if cGc and nGc and nGc~=cGc then
table.insert(_Fc,math.floor(bGc*1000+0.5)/1000)
end
cGc,dGc=nGc or cGc,dGc+math.abs(mGc)
else
aGc=hGc
end
bGc=hGc
if fGc%50==0 then
task.wait()
end
end
if bGc and eGc<=8 then
table.insert(_Fc,math.floor(bGc*1000+0.5)/1000)
GFc=GFc or{}
GFc[HFc.Name]={from=math.floor((aGc or 0)*1000+0.5)/1000,len=math.floor(dGc*1000+0.5)/1000,turns=_Fc,road=QFc}
end
end
end
if not GFc then
return
end
local oGc=bb.ld.map
P.maps[oGc]=P.maps[oGc]or{}
local pGc=P.maps[oGc].hidden
P.maps[oGc].hidden=GFc
if type(pGc)~=URe[2359]then
for qGc,rGc in pairs(GFc)do
F.log(1,URe[3047],string.format(URe[4626],qGc,rGc.len,tostring(rGc.road),math.floor((#rGc.turns-1)/2)))
end
F.saveSoon()
end
end
