return{samples=bb.samples,cache=R0c,spots=T0c,style=A0c.style,list=A0c.list,hybridHill=A0c.hybridHill}
end
local function U0c(V0c)
local W0c=0
for X0c,Y0c in pairs(V0c)do
local Z0c=bb.spotRec(X0c,Y0c)
if Z0c then
W0c=W0c+(tonumber(Z0c.wins)or 0)*200-((tonumber(Z0c.runs)or 0)-(tonumber(Z0c.wins)or 0))*1500
end
end
return W0c
end
local function _0c(a1c)
local b1c,c1c,d1c=0,0,0
for e1c,f1c in ipairs(D0c)do
local g1c=os.clock()
local h1c=gb.runRaw(y0c,z0c,{hpMul=f1c,layout=S0c(a1c),bg=true})
b1c,c1c,d1c=b1c+gb.objective(h1c),c1c+(tonumber(h1c.kills)or 0),d1c+(tonumber(h1c.wave)or 0)
task.wait(math.clamp((os.clock()-g1c)*3,0.25,v0c.pauseMax or 1.5))
if not x0c()then
return nil
end
end
F0c.n,F0c.run=F0c.n+1,F0c.run+1
return b1c/ #D0c*100+U0c(a1c),c1c/ #D0c,d1c/ #D0c
end
local function i1c(j1c)
local k1c={}
for l1c,m1c in pairs(j1c)do
k1c[l1c]=m1c
end
return k1c
end
local function n1c(o1c,p1c,q1c)
for r1c,s1c in pairs(o1c)do
if r1c~=p1c and(U.flat(s1c)-U.flat(q1c)).Magnitude<4.5 then
return true
end
end
return false
end
local t1c={spots=i1c(A0c.spots)}
t1c.s,t1c.kills,t1c.wave=_0c(t1c.spots)
if not t1c.s then
return bb.studyEnd(F0c,v0c,nil)
end
F0c.baseKills,F0c.baseWave=t1c.kills,t1c.wave
F0c.bestKills,F0c.bestWave=t1c.kills,t1c.wave
if E0c and E0c.aside==nil then
local u1c,v1c=i1c(t1c.spots),0
for w1c,x1c in ipairs(v0c.attackers)do
local y1c=E0c.spots[x1c.id]
local z1c=type(y1c)==URe[2359]and tonumber(y1c[1])and tonumber(y1c[3])and bb.nearSpot(x1c.spots,tonumber(y1c[1]),tonumber(y1c[3]))or nil
if z1c and z1c~=u1c[x1c.id]and not n1c(u1c,x1c.id,z1c)then
u1c[x1c.id]=z1c
v1c=v1c+1
end
end
if v1c>0 then
local A1c,B1c,C1c=_0c(u1c)
if not A1c then
return bb.studyEnd(F0c,v0c,t1c)
end
if A1c>t1c.s then
t1c={spots=u1c,s=A1c,kills=B1c,wave=C1c}
F0c.bestKills,F0c.bestWave=B1c,C1c
end
end
end
local D1c,E1c=U.now(),F0c.run
local function F1c(G1c)
if not(G1c.s and G1c.s>t1c.s+math.max(50,math.abs(t1c.s)*0.005))then
return false
end
t1c=G1c
F0c.bestKills,F0c.bestWave,F0c.better=G1c.kills,G1c.wave,(F0c.better or 0)+1
pcall(bb.bookSave,y0c,v0c,t1c,F0c)
return true
end
local function H1c()
if F0c.run-E1c>=60 or U.now()-D1c>240 then
D1c,E1c=U.now(),F0c.run
F.log(1,URe[3164],bb.studyWords(F0c))
end
end
local I1c={t1c}
for J1c,K1c in ipairs(v0c.attackers)do
local L1c={}
for M1c,N1c in ipairs(I1c)do
table.insert(L1c,N1c)
for O1c,P1c in ipairs(G0c[K1c.id]or{})do
if P1c~=N1c.spots[K1c.id]and not n1c(N1c.spots,K1c.id,P1c)then
local Q1c=i1c(N1c.spots)
Q1c[K1c.id]=P1c
local R1c,S1c,T1c=_0c(Q1c)
if not R1c then
return bb.studyEnd(F0c,v0c,t1c)
end
local U1c={spots=Q1c,s=R1c,kills=S1c,wave=T1c}
table.insert(L1c,U1c)
F1c(U1c)
H1c()
end
end
end
table.sort(L1c,function(V1c,W1c)
return(V1c.s or-1e18)>(W1c.s or-1e18)
end)
I1c={}
for X1c=1,math.min(bb.STUDY_BEAM,#L1c)do
table.insert(I1c,L1c[X1c])
end
end
local Y1c={}
for Z1c,_1c in ipairs(v0c.attackers)do
if G0c[_1c.id]and#G0c[_1c.id]>0 then
table.insert(Y1c,_1c.id)
end
end
while x0c()and#Y1c>0 do
local a2c=i1c(t1c.spots)
for b2c=1,math.min(2,#Y1c)do
local c2c=Y1c[math.random(#Y1c)]
local d2c=G0c[c2c]
local e2c=d2c[math.random(#d2c)]
if not n1c(a2c,c2c,e2c)then
a2c[c2c]=e2c
end
end
local f2c,g2c,h2c=_0c(a2c)
if not f2c then
break
end
F1c({spots=a2c,s=f2c,kills=g2c,wave=h2c})
H1c()
end
bb.studyEnd(F0c,v0c,t1c)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(i2c,j2c)
local k2c=N.PC.raycast(i2c+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not k2c then
return nil
end
if not N.PC.is_valid_raycast_hit(k2c.Instance,j2c)then
return nil
end
local l2c=k2c.Position
if bb.blockedSpot(l2c)then
return nil
end
local m2c=(tonumber(j2c.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(m2c*2,2.5,m2c*2)
bb.probe.CFrame=CFrame.new(l2c+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return l2c
end
function bb.studyInfinite()
if O.mapStudy==false or O.lowLag or not(bb.info and bb.infinite)or bb.kind==URe[2829]then
return
end
local n2c=bb.info
local function o2c()
return not F.alive or bb.finished or bb.result or F.where~=URe[2440]or O.mapStudy==false or bb.withOthers or bb.fastAlways
end
local p2c,q2c={},{}
for r2c,s2c in ipairs(bb.team or{})do
table.insert(p2c,s2c.u)
if not V.isFarm(s2c.id)and not V.allyBuff(s2c.id)and s2c.uuid~=bb.trainee and V.rows(s2c.id)then
local t2c,u2c=pcall(V.score,s2c.u,bb.mod)
table.insert(q2c,{e=s2c,id=s2c.id,sc=t2c and u2c or 0})
end
end
if#q2c==0 then
return
end
table.sort(q2c,function(v2c,w2c)
return v2c.sc>w2c.sc
end)
local function x2c()
local y2c,z2c={},0
for A2c,B2c in ipairs(q2c)do
for C2c,D2c in ipairs(bb.mine or{})do
local E2c=D2c:FindFirstChild(URe[2431])
local F2c=E2c and E2c:FindFirstChild(URe[2751])
if F2c and F2c.Value==B2c.e.uuid and E2c:FindFirstChild(URe[2752])and E2c.id.Value==B2c.id then
y2c[B2c.id]=D2c:GetPivot().Position
z2c=z2c+1
break
end
end
end
return y2c,z2c
end
local G2c=U.now()
local H2c,I2c=x2c()
while I2c< #q2c and U.now()-G2c<bb.STUDY_INF_WAIT do
task.wait(5)
if o2c()then
return
end
H2c,I2c=x2c()
end
if I2c==0 or o2c()then
return
end
local J2c={}
local function K2c(L2c)
local M2c=L2c.hybrid_placement and not L2c.hill_unit
local N2c=M2c and bb.hybridHill
local O2c=((L2c.hill_unit or N2c)and URe[3189]or(M2c and URe[4739])or URe[4740])..URe[2512]..tostring(L2c.override_hitbox_radius or URe[1278])
if J2c[O2c]then
return J2c[O2c]
end
local P2c={}
local Q2c=N2c and bb.hillData(L2c)or L2c
for R2c,S2c in ipairs(bb.cands or{})do
local T2c=bb.validOpen(S2c,Q2c)
if T2c then
table.insert(P2c,T2c)
end
if R2c%40==0 then
task.wait()
end
end
J2c[O2c]=P2c
return P2c
end
local U2c={info=n2c,team=gb.teamFrom(p2c,n2c.map),key=bb.bookKey(n2c),hard=1,scale=tonumber(n2c.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local V2c={spots={},style=URe[3356],hybridHill=bb.hybridHill and true or false}
for W2c,X2c in ipairs(q2c)do
local Y2c=(gb.holds(X2c.id)and not V.killFed(X2c.id))and true or false
local Z2c=Y2c and{}or table.clone(K2c(X2c.e.data))
if o2c()then
return
end
local _2c=H2c[X2c.id]
if _2c then
local a3c=bb.nearSpot(Z2c,_2c.X,_2c.Z)
if not a3c then
a3c=_2c
table.insert(Z2c,_2c)
end
V2c.spots[X2c.id]=a3c
end
if#Z2c>0 then
table.insert(U2c.attackers,{id=X2c.id,e=X2c.e,spots=Z2c})
end
end
U2c.base=V2c
bb.studyPool=U2c
F.log(1,URe[3164],string.format(URe[4820],bb.label(),I2c))
bb.studyRun(U2c)
end
function bb.studyWords(b3c)
if type(b3c)~=URe[2359]then
return URe[1278]
end
local function c3c(d3c,e3c)
return b3c.kills and string.format(URe[4754],math.floor((tonumber(d3c)or 0)+0.5))or string.format(URe[4821],tonumber(e3c)or 0,tonumber(b3c.hp)or 1)
end
return string.format(URe[4822],tostring(b3c.label),tonumber(b3c.n)or 0,tonumber(b3c.run)or 0,c3c(b3c.bestKills,b3c.bestWave),c3c(b3c.baseKills,b3c.baseWave),(b3c.better or 0)>0 and URe[4823]or URe[1278])
end
function bb.bookSave(f3c,g3c,h3c,i3c)
P.mapBook=type(P.mapBook)==URe[2359]and P.mapBook or{}
local j3c={}
for k3c,l3c in pairs(h3c.spots or{})do
j3c[k3c]={math.floor(l3c.X*10+0.5)/10,math.floor(l3c.Y*10+0.5)/10,math.floor(l3c.Z*10+0.5)/10}
end
P.mapBook[g3c.key]={spots=j3c,style=g3c.base.style,hp=i3c.hp,n=i3c.n,kills=h3c.kills and math.floor(h3c.kills+0.5)or nil,wave=h3c.wave and math.floor(h3c.wave*10+0.5)/10 or nil,base=i3c.baseWave and math.floor(i3c.baseWave*10+0.5)/10 or nil,label=i3c.label,map=f3c.map,killScore=i3c.kills,at=os.time()}
local m3c={}
for n3c,o3c in pairs(P.mapBook)do
table.insert(m3c,{k=n3c,at=type(o3c)==URe[2359]and tonumber(o3c.at)or 0})
end
if#m3c>bb.BOOK_MAX then
table.sort(m3c,function(p3c,q3c)
return p3c.at>q3c.at
end)
for r3c=bb.BOOK_MAX+1,#m3c do
P.mapBook[m3c[r3c].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(s3c,t3c,u3c)
if type(s3c)~=URe[2359]or s3c.ended then
return
end
s3c.ended=true
if u3c and t3c then
local v3c=bb.bookFor(t3c.info)
if v3c then
v3c.n=s3c.n
F.saveSoon()
elseif s3c.run>0 then
pcall(bb.bookSave,t3c.info,t3c,u3c,s3c)
end
end
if s3c.run>0 then
F.log(1,URe[3164],bb.studyWords(s3c))
end
end
function bb.studyReport()
local w3c=bb.info and bb.bookFor(bb.info)
if not w3c then
return nil
end
local x3c={}
for y3c,z3c in pairs(w3c.spots)do
if type(z3c)==URe[2359]then
x3c[y3c]={z3c[1],z3c[3]}
end
end
return{n=w3c.n,kills=w3c.kills,wave=w3c.wave,hp=w3c.hp,spots=x3c}
end
function bb.studyText()
if O.mapStudy==false then
return URe[3538]
end
if F.where==URe[2440]and type(bb.study)==URe[2359]and not bb.study.ended then
return URe[4824]..bb.studyWords(bb.study)
end
local A3c,B3c,C3c=0,nil,0
for D3c,E3c in pairs(type(P.mapBook)==URe[2359]and P.mapBook or{})do
if type(E3c)==URe[2359]then
A3c=A3c+1
if(tonumber(E3c.at)or 0)>C3c then
B3c,C3c=E3c,tonumber(E3c.at)or 0
end
end
end
if A3c==0 then
return URe[4825]
end
return string.format(URe[4826],A3c,tostring(B3c.label),tonumber(B3c.n)or 0,B3c.killScore and string.format(URe[4754],tonumber(B3c.kills)or 0)or string.format(URe[4827],tostring(B3c.wave)))
end
function bb.spotResult(F3c,G3c)
if not(bb.info and bb.info.timeLimit)then
for H3c,I3c in pairs(bb.layoutUsed or{})do
local J3c=bb.spotRec(H3c,I3c,true)
J3c.runs,J3c.wins=(tonumber(J3c.runs)or 0)+1,(tonumber(J3c.wins)or 0)+(F3c and 1 or 0)
end
end
local K3c,L3c=pcall(bb.labRecord,F3c,G3c)
if not K3c then
F.log(1,URe[2368],URe[4814]..tostring(L3c))
end
local M3c,N3c=pcall(bb.layoutResult,F3c,G3c)
if not M3c then
F.log(1,URe[2368],URe[4828]..tostring(N3c))
end
if not bb.infinite then
bb.styleRecord(F3c)
end
end
bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(O3c,P3c)
local Q3c=bb.bookKey(O3c)
P.layoutRec=type(P.layoutRec)==URe[2359]and P.layoutRec or{}
local R3c=P.layoutRec[Q3c]
if type(R3c)~=URe[2359]then
if not P3c then
return nil
end
R3c={at=os.time()}
P.layoutRec[Q3c]=R3c
if U.count(P.layoutRec)>80 then
local S3c,T3c
for U3c,V3c in pairs(P.layoutRec)do
local W3c=type(V3c)==URe[2359]and tonumber(V3c.at)or 0
if not T3c or W3c<T3c then
S3c,T3c=U3c,W3c
end
end
P.layoutRec[S3c]=nil
end
end
return R3c
end
function bb.layoutAdd(X3c,Y3c,Z3c,_3c,a4c)
X3c.runs,X3c.wins=(tonumber(X3c.runs)or 0)+1,(tonumber(X3c.wins)or 0)+(Y3c and 1 or 0)
X3c.sec,X3c.wave=type(X3c.sec)==URe[2359]and X3c.sec or{},type(X3c.wave)==URe[2359]and X3c.wave or{}
if Y3c and tonumber(Z3c)then
table.insert(X3c.sec,math.floor(Z3c+0.5))
end
table.insert(X3c.wave,tonumber(_3c)or 0)
if tonumber(a4c)then
X3c.kills=type(X3c.kills)==URe[2359]and X3c.kills or{}
table.insert(X3c.kills,math.floor(tonumber(a4c)))
while#X3c.kills>bb.LAYOUT_KEEP do
table.remove(X3c.kills,1)
end
end
while#X3c.sec>bb.LAYOUT_KEEP do
table.remove(X3c.sec,1)
end
while#X3c.wave>bb.LAYOUT_KEEP do
table.remove(X3c.wave,1)
end
end
function bb.layoutJudge(b4c,c4c,d4c,e4c,f4c)
f4c=f4c or URe[4829]
local g4c,h4c=tonumber(b4c and b4c.runs)or 0,tonumber(c4c and c4c.runs)or 0
if g4c<1 or h4c<bb.LAYOUT_CONTROL then
return nil
end
if e4c and type(b4c.kills)==URe[2359]and type(c4c.kills)==URe[2359]and#b4c.kills>=1 and#c4c.kills>=bb.LAYOUT_CONTROL then
local i4c,j4c=bb.labMedian(b4c.kills),bb.labMedian(c4c.kills)
if i4c and j4c and i4c<j4c*0.97 and(#b4c.kills>=2 or i4c<j4c*0.85)then
return string.format(URe[4830],i4c,j4c,f4c)
end
return nil
end
local k4c,l4c=(tonumber(b4c.wins)or 0)/g4c,(tonumber(c4c.wins)or 0)/h4c
if not d4c and l4c>=0.5 then
if k4c+0.25<l4c and(g4c>=2 or(k4c==0 and l4c>=0.9 and h4c>=3))then
return string.format(URe[4831],tonumber(b4c.wins)or 0,g4c,g4c==1 and URe[1278]or URe[2205],tonumber(c4c.wins)or 0,h4c,f4c)
end
local m4c,n4c=bb.labMedian(b4c.sec),bb.labMedian(c4c.sec)
if m4c and n4c and m4c>n4c*1.10 and(#b4c.sec>=2 or m4c>n4c*1.25)then
return string.format(URe[4832],math.floor(m4c/60),m4c%60,math.floor(n4c/60),n4c%60,f4c)
end
return nil
end
local o4c,p4c=bb.labMedian(b4c.wave),bb.labMedian(c4c.wave)
if o4c and p4c and o4c<p4c-math.max(1,p4c*0.03)and(g4c>=2 or o4c<p4c*0.85)then
return string.format(URe[4833],o4c,p4c,f4c)
end
return nil
end
function bb.layoutResult(q4c,r4c)
local s4c=bb.info
local t4c=bb.layoutSrc
if not(s4c and t4c)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not s4c.timeLimit then
return
end
local u4c=bb.wave()
local v4c=bb.layoutRecFor(s4c,true)
v4c.at=os.time()
local w4c=s4c.timeLimit~=nil
local x4c=s4c.killScore and true or nil
local y4c=x4c and(bb.killsEnd or bb.realKills())or nil
if t4c==URe[4799]then
local z4c=bb.bookFor(s4c)
if not z4c then
return
end
z4c.real=type(z4c.real)==URe[2359]and z4c.real or{}
bb.layoutAdd(z4c.real,q4c,r4c,u4c,y4c)
local A4c=z4c.aside==nil and bb.layoutJudge(z4c.real,v4c.own,w4c,x4c)or nil
if A4c then
z4c.aside={at=os.time(),why=A4c}
F.log(1,URe[4728],string.format(URe[4834],A4c))
end
elseif t4c==URe[4145]then
v4c.hiveUnit=type(v4c.hiveUnit)==URe[2359]and v4c.hiveUnit or{}
local B4c=v4c.hiveUnit
bb.layoutAdd(B4c,q4c,r4c,u4c,y4c)
local C4c=bb.bookFor(s4c)
local D4c=C4c and type(C4c.real)==URe[2359]and(tonumber(C4c.real.runs)or 0)>=bb.LAYOUT_CONTROL
local E4c=D4c and C4c.real or v4c.own
local F4c=bb.layoutJudge(B4c,E4c,w4c,x4c,D4c and URe[4835]or nil)
if F4c then
B4c.aside,B4c.why=os.time(),F4c
F.log(1,URe[4728],string.format(URe[4836],F4c))
elseif(tonumber(B4c.runs)or 0)>=bb.HIVE_TRIALS then
local G4c=E4c and bb.layoutJudge(E4c,B4c,w4c,x4c,URe[4837])
if G4c and C4c and type(bb.hiveUnitPlan)==URe[2359]then
for H4c,I4c in pairs(bb.hiveUnitPlan)do
C4c.spots[H4c]=I4c
end
C4c.real={runs=B4c.runs,wins=B4c.wins,sec=B4c.sec,wave=B4c.wave,kills=B4c.kills}
C4c.hive,C4c.aside=os.time(),nil
v4c.hiveUnit=nil
F.log(1,URe[4728],string.format(URe[4838],G4c))
else
B4c.aside,B4c.why=os.time(),URe[4839]
F.log(1,URe[4728],URe[4840])
end
end
else
v4c[t4c]=type(v4c[t4c])==URe[2359]and v4c[t4c]or{}
local J4c=v4c[t4c]
bb.layoutAdd(J4c,q4c,r4c,u4c,y4c)
if t4c==URe[4144]and J4c.aside==nil then
local K4c=bb.layoutJudge(J4c,v4c.own,w4c,x4c)
if K4c then
J4c.aside,J4c.why=os.time(),K4c
F.log(1,URe[4728],string.format(URe[4841],K4c))
end
