function bb.holdGain(Xgd,Ygd)
if bb.random or not Ygd or not bb.info then
return 0
end
local Zgd=V.attackInfo(Ygd.atk,Ygd.range)
if(Zgd.stun or 0)<=0 and(Zgd.slowTime or 0)<=0 then
return 0
end
local _gd=0
for ahd,bhd in ipairs(bb.mine or{})do
local chd=bhd._stats
local dhd=V.rows(chd.id.Value)
local ehd=dhd and dhd[math.min(chd.upgrade.Value,dhd.max)]
local fhd=ehd and ehd.atk and V.attackInfo(ehd.atk,ehd.range)
if fhd and((fhd.stun or 0)>0 or(fhd.slowTime or 0)>0)then
_gd=_gd+1
end
end
local ghd,hhd=gb.mask(bb.info.map,V.range(Xgd.u,0)*(bb.info.rangeScale or 1)),0
for ihd=1,gb.BINS do
if ghd[ihd]then
hhd=hhd+1
end
end
local jhd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local khd=(V.airFrom(Xgd.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(Zgd,bb.teamDps or 0,hhd/(math.max(0.1,jhd)*gb.BINS)*khd,_gd)
end
function bb.buffGain(lhd)
local mhd=V.allyBuff(lhd.id)
if not mhd or O.actives==false then
return 0
end
local nhd,ohd,phd=bb.buffShort(mhd)
local qhd=V.stackCap(mhd.attack)
local rhd,shd=pcall(V.range,lhd.u,0)
shd=(rhd and tonumber(shd)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local thd=qhd and O.community and tonumber(mhd.time)and tonumber(phd)
local function uhd(vhd,whd)
local xhd=math.floor(vhd*mhd.time/math.max(1,phd)+0.001)
return math.min(qhd,(1+whd)^xhd-1)
end
local yhd=0
for zhd,Ahd in ipairs(nhd)do
local Bhd=0
for Chd,Dhd in ipairs(nhd)do
if(Dhd.pos-Ahd.pos).Magnitude<=shd then
local Ehd=mhd.types[Dhd.base]
local Fhd=Ehd*mhd.uptime
if thd then
local Ghd,Hhd=uhd(Dhd.n,Ehd),Dhd.n+1
while Hhd<Dhd.n+6 and uhd(Hhd,Ehd)<=Ghd+0.001 do
Hhd=Hhd+1
end
Fhd=math.max(0,(uhd(Hhd,Ehd)-Ghd)/(Hhd-Dhd.n))
elseif qhd then
Fhd=math.max(0,math.min(qhd,(Dhd.n+1)*Ehd*mhd.uptime)-math.min(qhd,Dhd.n*Ehd*mhd.uptime))
end
Bhd=Bhd+Dhd.dps*Fhd
end
end
yhd=math.max(yhd,Bhd)
end
return yhd*(thd and 1 or 0.7)
end
function bb.buffWanted(Ihd)
return bb.buffGain(Ihd)>0.01*(bb.teamDps or 0)
end
bb.summonHist={}
function bb.summonRate()
local Jhd,Khd=U.now(),0
