local Qhd,Rhd=0,0
for Shd,Thd in ipairs(bb.mine or{})do
local Uhd=Thd._stats.id.Value
if V.BLESS.by[Uhd]then
Qhd=Qhd+1
end
if V.SUMMONER[Uhd]then
Rhd=Rhd+bb.liveDps(Thd,Uhd)
end
end
if Qhd>=V.BLESS.cap then
return 0
end
local Vhd=math.max(bb.summonRate(),Rhd*(1+V.BLESS.dmg*Qhd))
return Vhd/(1+V.BLESS.dmg*Qhd)*V.BLESS.dmg
end
function bb.liveDps(Whd,Xhd)
local Yhd=Whd:FindFirstChild(URe[2431])
if not(Yhd and Yhd:FindFirstChild(URe[2810])and Yhd:FindFirstChild(URe[2809])and Yhd:FindFirstChild(URe[2627]))then
return 0
end
local Zhd=V.SUMMONER[Xhd]
local _hd=math.max(0.1,Yhd.attack_cooldown.Value*(Zhd and Zhd.rate or 1))
local aid=(Zhd and Zhd.atk)or(Yhd:FindFirstChild(URe[2475])and Yhd.primary_attack.Value)or nil
local cid=Yhd:FindFirstChild(URe[2462])and tonumber(Yhd.upgrade.Value)or 0
local did=0
for eid,fid in ipairs({URe[4460],URe[4922]})do
local gid=Yhd:FindFirstChild(fid)
if gid then
did=math.max(did,tonumber(gid.Value)or 0)
end
end
local hid,iid=V.types(Xhd)
local jid=URe[4466]..tostring(iid)
local kid=1+(tonumber(Whd:GetAttribute(jid))or tonumber(Yhd:GetAttribute(jid))or 0)
local lid=Yhd.damage.Value*V.galeDps(Xhd,cid)
return(Yhd.damage.Value/_hd*V.aoe(aid,Yhd.range.Value)*(1+did*0.5)*V.secK(Xhd,cid)+lid)*V.elem(Xhd,bb.mod)*V.nudge(Xhd)*kid*bb.reincMul(Whd)
end
function bb.fullDps(nid,oid)
local qid=bb.liveDps(nid,oid)
local rid=V.rows(oid)
local sid=nid:FindFirstChild(URe[2431])
local tid=sid and sid:FindFirstChild(URe[2462])and tonumber(sid.upgrade.Value)or 0
if not(rid and rid.max)or tid>=rid.max then
return qid
end
local function vid(wid)
local xid=rid[math.min(wid,rid.max)]
if not xid or(tonumber(xid.cd)or 0)<=0 then
return 0
end
return(tonumber(xid.damage)or 0)/xid.cd*V.aoe(xid.atk,xid.range)*V.secK(oid,wid)
end
local yid,zid=vid(tid),vid(rid.max)
if yid<=0 or zid<=0 then
return qid
end
return qid*math.max(1,zid/yid)
end
function bb.inReach(Aid,Bid)
if not V.SUMMONER[Bid]then
return false
end
local Cid=Aid:FindFirstChild(URe[2431])
local Did=Cid and Cid:FindFirstChild(URe[2627])
if not Did then
return false
end
local Eid=0
for Fid,Gid in ipairs(bb.mine or{})do
local Hid=Gid:FindFirstChild(URe[2431])
if Hid and Hid:FindFirstChild(URe[2752])and V.BLESS.by[Hid.id.Value]then
Eid=Eid+1
end
end
local Iid=Did.Value*V.reachOf(Bid,Eid)
local Jid=Aid:GetPivot().Position
for Kid,Lid in ipairs(bb.enemies or{})do
local Mid=Lid.pos
if Mid and Vector3 .new(Mid.X-Jid.X,0,Mid.Z-Jid.Z).Magnitude<=Iid then
return true
end
end
return false
end
function bb.reincMul(Nid)
local Oid=Nid and Nid:FindFirstChild(URe[2762])
local Pid=Oid and Oid:FindFirstChild(URe[4923])
local Qid=Pid and tonumber(Pid.Value)or 0
if Qid<=0 then
return 1
end
local Rid=Nid:FindFirstChild(URe[2431])
local Sid=Rid and Rid:FindFirstChild(URe[2752])and Rid.id.Value
return 1+Qid*((Sid and V.reincAdd(Sid))or 0.5)
end
function bb.reincNext(Tid)
local Uid=bb.reinc
return(type(Uid)==URe[2359]and Uid.id==Tid and(Uid.sold or 0)>0)and 1+(tonumber(Uid.add)or 0)or 1
end
function bb.reincGain(Vid)
local Wid=bb.reinc
if type(Wid)~=URe[2359]or Wid.push==nil or Wid.push~=Vid or(tonumber(bb.pressure)or 0)>=gb.REINC_PUSH then
