local ztd=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local Atd=mb.weatherStrength(mb.weatherNow())
local Btd=table.find(mb.CARD_PICKS,O.huntCards)and O.huntCards or URe[1282]
local Ctd,Dtd,Etd,Ftd
