end
local Otd=type(Itd)==URe[2359]and mb.cardGems(Itd,xtd)or 0
local Ptd=Jtd>=1 or(bb.fhP*Jtd>=ytd and not ztd)
local Qtd=math.log(math.max(0.05,Jtd))
local Rtd=Qtd*mb.STRENGTH_GEMS+(Ptd and Otd or-1000)
local Std=mb.cardLuck(Itd)
if Btd==URe[1280]and Ptd and Std>0 then
Rtd=2e6+Std*1e4+Otd
elseif Btd==URe[2377]and Ptd then
Rtd=1e6+mb.cardPearls(Itd,xtd)*10+Otd+Qtd
elseif Btd==URe[2939]then
Rtd=Qtd*1e6+Otd
