local qvd,rvd=pcall(bb.liveDps,ovd,pvd)
rvd=qvd and rvd or 0
local svd=V.types(pvd)
lvd=lvd+rvd
if svd[kvd]or svd[kvd..URe[2578]]then
mvd=mvd+rvd
end
end
end
local tvd=0
for uvd,vvd in ipairs(bb.mine or{})do
if not V.isFarm(vvd._stats.id.Value)then
tvd=tvd+1
end
end
local wvd=tvd/(tvd+4)
return wvd*(lvd>0 and mvd/lvd or 0.5)+(1-wvd)*0.5
end
function bb.resistOf(xvd)
local yvd=V.types(xvd)
local zvd=0
for Avd,Bvd in pairs(bb.fhResist or{})do
local Cvd=tostring(Avd):gsub(URe[4319],URe[1278])
