function bb.rogueEffect(Dvd)
local Evd,Fvd,Gvd=Dvd.type,tonumber(Dvd.amount)or 0,tostring(Dvd.stat or URe[1278])
if Evd==URe[2921]then
return 1,math.abs(Fvd)
end
if Evd==URe[4454]or Evd==URe[4459]or Evd==URe[4455]then
if Gvd==URe[2809]then
return math.max(0.3,1+Fvd),0
end
if Gvd==URe[2627]then
return math.max(0.5,1+Fvd/2),0
end
if Gvd:find(URe[3179])then
return 1/math.max(0.3,1+Fvd),0
end
return 1,0
end
if Evd==URe[5080]then
if Gvd==URe[2809]then
return math.max(0.3,Fvd),0
end
if Gvd==URe[2627]then
return math.max(0.5,1+(Fvd-1)/2),0
end
if Gvd:find(URe[3179])then
return 1/math.max(0.3,Fvd),0
end
return 1,0
end
if Evd==URe[4461]then
return 1+Fvd/3,0
end
if Evd==URe[4467]then
return 1/math.max(0.3,1+Fvd),0
end
if Evd==URe[5081]then
return math.max(0.2,1-bb.rogueShare(Dvd.damage_type)*(1-100/(100+Fvd))),0
end
if Evd==URe[5082]then
return 1+bb.rogueShare(Dvd.damage_type)*Fvd,0
end
if Evd==URe[5083]then
return math.max(0.5,1-Fvd*0.5),0
end
if Evd==URe[5084]then
return math.max(0.5,1-Fvd*0.2),0
end
if Evd==URe[5085]then
return 1+Fvd*0.1,0
end
if Evd==URe[5086]then
return 1/math.max(0.3,1+Fvd*0.5),0
end
if Evd==URe[5087]then
return math.max(0.5,1-Fvd*0.1),0
end
if Evd==URe[4462]then
return 1/math.max(0.3,1+Fvd),0
end
if Evd==URe[4468]then
return math.max(0.3,1-Fvd*20),0
end
if Evd==URe[4469]then
return math.max(0.5,1-Fvd*0.03),0
end
if Evd==URe[5088]then
return 0.95,0
end
if Evd==URe[4470]then
return math.max(0.5,1-Fvd),0
end
if Evd==URe[5089]then
return 1+math.min(0.3,Fvd/40000),0
end
if Evd==URe[4463]then
return 1/math.max(0.3,1+Fvd/2),0
end
if Evd==URe[5090]then
return 0.8,0
end
if Evd==URe[5091]then
local Hvd=math.max(1,math.abs(Fvd))*math.max(1,math.abs(tonumber(Dvd.tier)or 1))
return Dvd._type==URe[5092]and 1.1^Hvd or 0.8^Hvd,0
