end
end
vJd=vJd or mJd[1]
local FJd=vJd.dps*bb.airBoost(vJd.m)*bb.reach(vJd.m)*(lJd==bb.planId and 2 or 1)
if(bb.mergeIds[lJd]or lJd==bb.planId)and(sJd or _Id[lJd])and(not kJd or FJd>kJd.score)then
kJd={id=lJd,top=vJd,fresh=sJd,near=tJd or 0,n=uJd or 0,coming=_Id[lJd],score=FJd}
