bb.planId,bb.freshM=kJd and kJd.id,kJd and kJd.fresh and kJd.fresh.m
bb.mergeHeldAt=(PId and kJd and kJd.fresh)and(bb.mergeHeldAt or bb.wave())or nil
if not kJd then
