end
local GJd,HJd=bb.wave(),(bb.total or 30)-bb.wave()
local IJd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local JJd=kJd.fresh
local KJd=not IJd and HJd>3
kJd.waits=JJd and JJd.lvl<=kJd.top.lvl and kJd.top.lvl<kJd.top.max and KJd or false
local LJd=(not JJd or JJd.lvl>=kJd.top.lvl)and kJd.coming and KJd
local MJd=bb.cloneCard and kJd.top.lvl>=kJd.top.max and KJd
local NJd=JJd and JJd.lvl>kJd.top.lvl and kJd.near<0.3*JJd.dps
kJd.ready=PId and JJd~=nil and not NJd and(not(kJd.waits or LJd or MJd)or GJd-(bb.mergeHeldAt or GJd)>=5)
bb.holdNoCardAt=(kJd.waits and not PId)and(bb.holdNoCardAt or GJd)or nil
kJd.hold=kJd.waits and(PId or GJd-(bb.holdNoCardAt or GJd)<4)
bb.mergePlan=kJd
F.status(URe[5127],JJd and string.format(URe[5226],V.name(kJd.id),kJd.n,kJd.n==1 and URe[5227]or URe[5228],JJd.lvl,kJd.ready and URe[5229]or(PId and URe[5230]or URe[5231]))or string.format(URe[5232],V.name(kJd.id)))
end
function bb.mergeHold(OJd)
