function bb.spells()
local ZKd=N.session()
local _Kd=ZKd and ZKd.ingame_spells
if type(_Kd)~=URe[2359]or bb.spellBusy then
return
end
local aLd=bb.money()
local bLd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local cLd,dLd,eLd
for fLd,gLd in ipairs(bb.mine)do
local hLd=gLd._stats.id.Value
if not V.isFarm(hLd)and not V.allyBuff(hLd)and hLd~=URe[4648]then
local iLd,jLd=pcall(bb.liveDps,gLd,hLd)
local kLd=iLd and jLd and jLd*bb.airBoost(gLd)*bb.reach(gLd)
if kLd and(not eLd or kLd>eLd)then
cLd,dLd,eLd=gLd,jLd,kLd
end
end
end
local lLd=bb.mergePlan
local mLd={}
for nLd,oLd in pairs(_Kd)do
table.insert(mLd,{slot=nLd,spell=oLd,rank=bb.SPELL_ORDER[oLd]or 9})
end
table.sort(mLd,function(pLd,qLd)
return pLd.rank<qLd.rank
end)
bb.spellWant=nil
bb.cloneNote=nil
