end
end
local ALd=xLd and(bb.buffCount[xLd]or 0)<2
if uLd==URe[5237]and aLd>=1000 and(ALd or cLd)then
if ALd then
vLd,wLd=xLd,URe[5238]
else
vLd,wLd=cLd,URe[5239]
end
elseif uLd==URe[5160]and lLd and lLd.ready then
if aLd>=1000 then
vLd,wLd=lLd.fresh.m,string.format(URe[5240],lLd.n,lLd.n==1 and URe[5227]or URe[5228])
bb.mergeBefore={own=lLd.fresh.dps,near=lLd.near,lvl=lLd.fresh.lvl,top=lLd.top.lvl}
else
bb.spellWant=bb.spellWant or{cost=1000,why=URe[5241]..V.name(lLd.id)}
end
elseif uLd==URe[5160]and aLd>=1000 and not bLd and not(lLd and lLd.fresh)and bb.farmMergeOk()and bb.farmMergePair()then
local BLd,CLd,DLd=bb.farmMergePair()
vLd=BLd
wLd=string.format(URe[5242],DLd,V.name(BLd._stats.id.Value))
bb.farmMergeBefore={own=tonumber(BLd._stats.farm_amount.Value)or 0,inc=CLd}
elseif uLd==URe[5224]then
local ELd=not bLd and lLd and lLd.fresh and lLd.top.lvl<lLd.top.max
