local FLd=ELd and bb.wave()-bb.cloneWaitAt<5
local GLd,HLd
if not bLd and lLd and lLd.fresh and lLd.top.lvl>=lLd.top.max then
GLd,HLd=lLd.top.m,URe[5243]
elseif not FLd and cLd then
GLd,HLd=cLd,bLd and URe[5244]or URe[5245]
end
if FLd then
bb.cloneNote=string.format(URe[5246],V.name(lLd.id),lLd.top.lvl,lLd.top.max,5-(bb.wave()-bb.cloneWaitAt))
end
if GLd and aLd>=5000 then
vLd,wLd=GLd,HLd
elseif GLd then
local ILd,JLd=pcall(bb.liveDps,GLd,GLd._stats.id.Value)
JLd=ILd and tonumber(JLd)or 0
if JLd>=(bb.bestRate or 0)*5000*0.5 then
bb.spellWant=bb.spellWant or{cost=5000,why=URe[5247]..V.name(GLd._stats.id.Value),rate=JLd/5000}
bb.cloneNote=URe[5248]..V.name(GLd._stats.id.Value)
else
