vLd,wLd=KLd,LLd
elseif KLd then
bb.spellWant=bb.spellWant or{cost=10000,why=URe[5250]..LLd..URe[3040]}
end
elseif uLd==URe[2457]and aLd>=10000 and not bLd and bb.summonWorth()then
vLd,wLd=false,URe[5251]
elseif uLd==URe[5161]and aLd>=2500 and not bLd and bb.summonWorth()then
vLd,wLd=false,URe[5252]
end
if wLd then
bb.spellBusy=true
local MLd={}
for NLd,OLd in ipairs(workspace._UNITS:GetChildren())do
