PLd={id=QLd.id.Value,pos=vLd:GetPivot().Position,dps=RLd and tonumber(SLd)or 0,lvl=QLd.upgrade.Value,spent=QLd:FindFirstChild(URe[4670])and tonumber(QLd.total_spent.Value)or 0}
end
task.spawn(function()
local TLd
if vLd then
TLd=F.request(URe[5168],URe[5169],tLd,vLd)
else
TLd=F.request(URe[5168],URe[5169],tLd)
end
task.wait(1.5)
local ULd=vLd and V.name(vLd._stats.id.Value)or URe[1278]
if TLd and(N.session().ingame_spells or{})[tLd]~=uLd then
F.log(1,URe[5148],string.format(URe[5253],bb.SPELL_NAMES[uLd]or tostring(uLd),vLd and(URe[2962]..ULd)or URe[1278],wLd))
F.status(URe[5031],string.format(URe[5254],bb.SPELL_NAMES[uLd]or tostring(uLd),vLd and(URe[2962]..ULd)or URe[1278],wLd))
if uLd==URe[5160]then
if PLd and V.isFarm(PLd.id)then
pcall(bb.farmMergeMeasure,vLd)
