if uLd==URe[5237]and vLd then
bb.buffCount[vLd]=(bb.buffCount[vLd]or 0)+1
end
if(uLd==URe[5224]or uLd==URe[5157])and PLd then
pcall(bb.newUnitMeasure,uLd,vLd,ULd,PLd,MLd)
end
else
F.backoff(URe[5168],15)
F.log(2,URe[5148],tostring(uLd)..URe[5255]..(vLd and(URe[2962]..ULd)or URe[1278]))
end
bb.spellBusy=false
end)
return
end
end
end
function bb.trainCount()
local VLd=P.train.on
if not(VLd and bb.trainee)then
return
end
local WLd=0
for XLd,YLd in ipairs(bb.mine)do
local ZLd=YLd._stats
local _Ld=ZLd:FindFirstChild(URe[2751])and ZLd.uuid.Value
local aMd=_Ld==bb.trainee and ZLd:FindFirstChild(VLd.what==URe[3030]and URe[5256]or URe[2764])
if aMd then
WLd=WLd+(tonumber(aMd.Value)or 0)
end
end
bb.trainTk=math.max(bb.trainTk or 0,WLd)
F.status(URe[3697],string.format(URe[5257],V.name(VLd.id),bb.trainTk,VLd.what,U.fmt(VLd.have+(VLd.got or 0)+bb.trainTk),U.fmt(VLd.need)))
end
function bb.trainDone(bMd,cMd)
local dMd=P.train.on
if not(dMd and bb.trainee)then
return
end
bb.trainCount()
local eMd=bb.trainTk or 0
dMd.got=(dMd.got or 0)+eMd
local fMd=P.trainSim[bMd]and tonumber(P.trainSim[bMd].tk)
if not bb.joinedMid then
local gMd=P.train.real[bMd]or{n=0,sum=0}
gMd.n,gMd.sum=gMd.n+1,gMd.sum+eMd
P.train.real[bMd]=gMd
if fMd and fMd>0 then
local hMd=P.train.cal
hMd.real,hMd.sim,hMd.n=(hMd.real or 0)+eMd,(hMd.sim or 0)+fMd,(hMd.n or 0)+1
end
end
table.insert(P.train.log,1,{key=bMd,got=eMd,won=cMd,at=os.time()})
while#P.train.log>20 do
table.remove(P.train.log)
end
F.log(1,URe[3690],string.format(URe[5258],V.name(dMd.id),eMd,dMd.what,cMd and URe[3155]or URe[3156],fMd and string.format(URe[5259],fMd)or URe[1278],U.fmt(ib.realHave(dMd)),U.fmt(dMd.need)))
if not cMd then
P.train.bad[bMd]=os.time()+3600
F.log(1,URe[3690],URe[5260])
end
end
