if Sle.on then
Qle=Rle
end
end
Qle=(Qle-1+(Gle==Kle.PageDown and 1 or-1))% #Lle+1
Ile.setFocus(nil)
Jle:SelectTab(Lle[Qle].name)
return true
end
if Gle==Kle.Tab or Gle==Kle.Down or Gle==Kle.Up then
