if#Tle==0 then
return true
end
local Ule=Gle==Kle.Up or(Gle==Kle.Tab and Hle)
local Vle=table.find(Tle,Ile.cur)
if not Vle then
Vle=Ule and#Tle or 1
else
Vle=(Vle-1+(Ule and-1 or 1))% #Tle+1
end
Ile.setFocus(Tle[Vle])
return true
end
if not Ile.cur then
return false
end
if Gle==Kle.Return or Gle==Kle.KeypadEnter or Gle==Kle.Space then
if Ile.cur.activate then
Ile.cur.activate()
end
return true
end
if Gle==Kle.Left or Gle==Kle.Right then
if Ile.cur.adjust then
Ile.cur.adjust(Gle==Kle.Right and 1 or-1)
end
return true
end
if Gle==Kle.Escape then
Ile.setFocus(nil)
return true
end
return false
end
function nb.K.keys(Wle)
